#[cfg(test)]
mod tests {
    use std::collections::HashSet;

    use super::*;

    #[test]
    fn generated_loot_context_params_are_complete_unique_and_ordered() {
        assert_eq!(VANILLA_LOOT_CONTEXT_PARAMS.len(), 15);
        assert_eq!(
            VANILLA_LOOT_CONTEXT_PARAMS
                .iter()
                .map(|param| param.resource_id())
                .collect::<Vec<_>>(),
            [
                "minecraft:this_entity",
                "minecraft:interacting_entity",
                "minecraft:target_entity",
                "minecraft:last_damage_player",
                "minecraft:damage_source",
                "minecraft:attacking_entity",
                "minecraft:direct_attacking_entity",
                "minecraft:origin",
                "minecraft:block_state",
                "minecraft:block_entity",
                "minecraft:tool",
                "minecraft:explosion_radius",
                "minecraft:enchantment_level",
                "minecraft:enchantment_active",
                "minecraft:additional_cost_component_allowed",
            ]
        );
        assert_eq!(
            VANILLA_LOOT_CONTEXT_PARAMS
                .iter()
                .map(|param| param.resource_id())
                .collect::<HashSet<_>>()
                .len(),
            VANILLA_LOOT_CONTEXT_PARAMS.len()
        );
    }

    #[test]
    fn generated_loot_entity_targets_preserve_order_mapping_and_lookup() {
        assert_eq!(VANILLA_LOOT_ENTITY_TARGETS.len(), 6);
        assert_eq!(
            VANILLA_LOOT_ENTITY_TARGETS
                .iter()
                .map(|target| (target.serialized_name, target.context_param))
                .collect::<Vec<_>>(),
            [
                ("this", VanillaLootContextParam::ThisEntity),
                ("attacker", VanillaLootContextParam::AttackingEntity),
                (
                    "direct_attacker",
                    VanillaLootContextParam::DirectAttackingEntity
                ),
                (
                    "attacking_player",
                    VanillaLootContextParam::LastDamagePlayer
                ),
                ("target_entity", VanillaLootContextParam::TargetEntity),
                (
                    "interacting_entity",
                    VanillaLootContextParam::InteractingEntity
                ),
            ]
        );
        for target in VANILLA_LOOT_ENTITY_TARGETS {
            assert_eq!(
                vanilla_loot_entity_target(target.serialized_name),
                Some(target)
            );
        }
        assert!(vanilla_loot_entity_target("missing").is_none());
    }

    #[test]
    fn generated_loot_context_param_sets_preserve_order_membership_and_lookup() {
        assert_eq!(VANILLA_LOOT_CONTEXT_PARAM_SETS.len(), 26);
        assert_eq!(
            VANILLA_LOOT_CONTEXT_PARAM_SETS
                .iter()
                .map(|entry| (entry.constant_name, entry.resource_id))
                .collect::<Vec<_>>(),
            [
                ("EMPTY", "minecraft:empty"),
                ("CHEST", "minecraft:chest"),
                ("COMMAND", "minecraft:command"),
                ("SELECTOR", "minecraft:selector"),
                ("VILLAGER_TRADE", "minecraft:villager_trade"),
                ("FISHING", "minecraft:fishing"),
                ("ENTITY", "minecraft:entity"),
                ("EQUIPMENT", "minecraft:equipment"),
                ("ARCHAEOLOGY", "minecraft:archaeology"),
                ("GIFT", "minecraft:gift"),
                ("PIGLIN_BARTER", "minecraft:barter"),
                ("VAULT", "minecraft:vault"),
                ("ADVANCEMENT_REWARD", "minecraft:advancement_reward"),
                ("ADVANCEMENT_ENTITY", "minecraft:advancement_entity"),
                ("ADVANCEMENT_LOCATION", "minecraft:advancement_location"),
                ("BLOCK_USE", "minecraft:block_use"),
                ("ALL_PARAMS", "minecraft:generic"),
                ("BLOCK", "minecraft:block"),
                ("SHEARING", "minecraft:shearing"),
                ("ENTITY_INTERACT", "minecraft:entity_interact"),
                ("BLOCK_INTERACT", "minecraft:block_interact"),
                ("ENCHANTED_DAMAGE", "minecraft:enchanted_damage"),
                ("ENCHANTED_ITEM", "minecraft:enchanted_item"),
                ("ENCHANTED_LOCATION", "minecraft:enchanted_location"),
                ("ENCHANTED_ENTITY", "minecraft:enchanted_entity"),
                ("HIT_BLOCK", "minecraft:hit_block"),
            ]
        );
        for entry in VANILLA_LOOT_CONTEXT_PARAM_SETS {
            assert_eq!(
                vanilla_loot_context_param_set(entry.resource_id),
                Some(entry)
            );
            let required = entry.required.iter().copied().collect::<HashSet<_>>();
            let optional = entry.optional.iter().copied().collect::<HashSet<_>>();
            assert_eq!(required.len(), entry.required.len());
            assert_eq!(optional.len(), entry.optional.len());
            assert!(required.is_disjoint(&optional));
            for param in VANILLA_LOOT_CONTEXT_PARAMS {
                assert_eq!(
                    entry.allows(*param),
                    required.contains(param) || optional.contains(param)
                );
            }
        }
        assert!(vanilla_loot_context_param_set("minecraft:missing").is_none());
    }
}
